function initView(){fetchStats(),fetchStatus(),fetchList()}function fetchStats(){sendAjax({endpoint:"/Stock/stats",type:"POST",data:componentFilters,beforeSend:function(){loadingStats("stats")},onSuccess:t=>{setTimeout(()=>{t.success?buildStats(t.data):Notify(2,t.message)},1200)}})}function fetchStatus(){sendAjax({endpoint:"/Stock/status",onSuccess:t=>{setTimeout(()=>{t.success?buildStatus(t.data):Notify(2,t.message)},1200)}})}function fetchList(){sendAjax({endpoint:"/Stock/list",type:"POST",data:componentFilters,beforeSend:function(){loadingTable("lists")},onSuccess:t=>{setTimeout(()=>{t.success?buildList(t.data):Notify(2,t.message)},1200)}})}function buildList(t){let s="";t.forEach(t=>{s+=`<tr class="fw-semibold bg-info-subtle">\n            <td>${t.producto}</td>\n            <td></td>\n            <td class="text-nowrap">\n                <div class="d-flex align-items-center justify-content-end">\n                    <span class="material-symbols-outlined icon-fill text-primary">weight</span>\n                    <span class="ms-3">${t.totalCantidad} Lbs</span>\n                </div>\n            </td>\n            <td class="text-end">${t.totalToneladas} T</td>\n            <td class="text-end">\n                <div class="d-flex align-items-center justify-content-end">\n                    <span class="material-symbols-outlined icon-fill text-primary">package_2</span>\n                    <span class="ms-3">${t.totalPaquetes}</span>\n                </div>\n            </td>\n            <td>-</td>\n            <td></td>\n        </tr>`,t.details.forEach(n=>{t.productoId;const e=n.subproductoId;s+=`<tr class="bg-light">\n                <td class="ps-5 fw-bold">\n                    <div class="d-flex align-items-center">\n                        <span class="material-symbols-outlined icon-fill fs-2 text-gray-100">circle</span>\n                        <span class="ms-3">${n.subproducto}</span>\n                    </div>\n                </td>\n                <td></td>\n                <td class="text-end">${n.totalCantidad} Lbs</td>\n                <td class="text-end">${n.totalToneladas} T</td>\n                <td class="text-end">${n.totalPaquetes}</td>\n                <td>-</td>\n                <td>\n                    <div class="d-flex align-items-center justify-content-center user-select-none">\n                        <div class="d-flex align-items-center">\n                            <a href="../Stock/${e}" class="material-symbols-outlined edit h3 text-gray-100" title="Administrar">settings</a>\n                        </div>\n                    </div>\n                </td>\n            </tr>`,n.details.forEach(t=>{const n=t.ultima_actualizacion,e=new Date(n.replace(" ","T"));s+=`<tr>\n                    <td class="ps-5">\n                        <div class="ps-5">\n                            <span class="material-symbols-outlined icon-fill fs-2 text-gray">circle</span>\n                            <span class="ms-3"> ${t.ubicacion}</span>\n                        </div>\n                    </td>\n                    <td>${t.presentacion}</td>\n                    <td class="text-end">${t.cantidad} Lbs</td>\n                    <td class="text-end">${t.toneladas} T</td>\n                    <td class="text-end">\n                        <div class="fw-bold fs-3">${t.paquetes}</div>\n                        <div class="text-muted fs-2">${null!=t.unidades?`${Number(t.unidades)} U`:""}</div>\n                    </td>\n                    <td>\n                        <div class="fw-bold fs-3">${formatoRelativo(e)}</div>\n                        <div class="text-muted">${formatoFechaCorta(e)}</div>\n                    </td>\n                    <td></td>\n                </tr>`})})});let n=`<div class="table-responsive border rounded-3 shadow mt-3">\n            <table class="table align-middle mb-0 text-dark fs-4">\n                <thead>\n                    <tr>\n                        <th>Producto / Subproducto / Ubicación</th>\n                        <th>Presentación</th>\n                        <th class="text-end">Cantidad (Libras)</th>\n                        <th class="text-end">Cantidad (Toneladas)</th>\n                        <th class="text-end">Paquetes</th>\n                        <th>Última Actualización</th>\n                        <th class="text-center">Acciones</th>\n                    </tr>\n                </thead>\n                <tbody>\n                ${s}\n                </tbody>\n            </table>\n        </div>`;$("#lists").empty().html(n)}function buildStatus(t){const s=t.locations,n=t.products;let e="",a="";s.forEach(t=>{e+=`<option value="${t.id}">${t.name}</option>`}),n.forEach(t=>{a+=`<option value="${t.id}">${t.name}</option>`});let d=`\n    <div class="d-flex flex-column flex-md-row gap-2">\n            <select class="form-select form-select-lg rounded-3 mb-md-0" id="products">\n                <option value="">Todos los Productos</option>\n                ${a}\n            </select>\n            <select class="form-select form-select-lg rounded-3 mb-md-0" id="locations">\n                <option value="">Todas las ubicaciones</option>\n                ${e}\n            </select>\n        </div>`;$("#status").empty().html(d)}function buildStats(t){const s=t.last_update||"";let n="";s&&(n=new Date(s.replace(" ","T")));let e=`\n    <div class="row g-3 mb-3 user-select-none">\n            <div class="col-md-3">\n                <div class="card shadow border mb-1 card-hover h-100">\n                    <div class="card-body d-flex align-items-center gap-3 p-2">\n                        <div class="bg-primary-subtle rounded-4 p-3 d-flex justify-content-center align-items-center">\n                            <span class="material-symbols-outlined text-primary" style="font-size: 2rem;">package_2</span>\n                        </div>\n                        <div>\n                            <div class="text-muted fw-bold h5">Total Almacenado</div>\n                            <div class="fw-semibold h4">${Number((t.total_quantity/2200).toFixed(3))} T</div>\n                            <div class="text-muted h6">${Number(t.total_quantity)||0} Lbs</div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n            <div class="col-md-3">\n                <div class="card shadow border mb-1 card-hover h-100">\n                    <div class="card-body d-flex align-items-center gap-3 p-2">\n                        <div class="bg-warning-subtle rounded-4 p-3 d-flex justify-content-center align-items-center">\n                            <span class="material-symbols-outlined text-warning" style="font-size: 2rem;">package</span>\n                        </div>\n                        <div>\n                            <div class="text-muted fw-bold h5">Total Paquetes</div>\n                            <div class="fw-semibold h4">${Number(t.total_packages)||0}</div>\n                            <div class="text-muted h6">Paquetes disponibles</div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n            <div class="col-md-3">\n                <div class="card shadow border mb-1 card-hover h-100">\n                    <div class="card-body d-flex align-items-center gap-3 p-2">\n                        <div class="bg-success-subtle rounded-4 p-3 d-flex justify-content-center align-items-center">\n                            <span class="material-symbols-outlined text-success" style="font-size: 2rem;">content_paste</span>\n                        </div>\n                        <div>\n                            <div class="text-muted fw-bold h5">Productos Activos</div>\n                            <div class="fw-semibold h4">${t.total_items||0}</div>\n                            <div class="text-muted h6">Productos registrados</div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n            <div class="col-md-3">\n                <div class="card shadow border mb-1 card-hover h-100">\n                    <div class="card-body d-flex align-items-center gap-3 p-2">\n                        <div class="bg-info-subtle rounded-4 p-3 d-flex justify-content-center align-items-center">\n                            <span class="material-symbols-outlined text-info" style="font-size: 2rem;">calendar_today</span>\n                        </div>\n                        <div>\n                            <div class="text-muted fw-bold h5">Última Actualización</div>\n                            <div class="fw-semibold h4">${formatoRelativo(n)}</div>\n                            <div class="text-muted h6">${formatoFechaCorta(n)}</div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n    `;$("#stats").empty().html(e)}function formatoFechaCorta(t){if(""===t)return"";var s=String(t.getDate()).padStart(2,"0"),n=String(t.getMonth()+1).padStart(2,"0"),e=t.getFullYear();return`${s}/${n}/${e}`}function formatoRelativo(t){if(""===t)return"";const s=new Date,n=new Date(s.getFullYear(),s.getMonth(),s.getDate()),e=new Date(t.getFullYear(),t.getMonth(),t.getDate()),a=n-e,d=Math.floor(a/864e5),i=t.toLocaleTimeString("es-ES",{hour:"2-digit",minute:"2-digit"});return 0===d?`Hoy, ${i}`:1===d?`Ayer, ${i}`:`Hace ${d} días, ${i}`}$(document).ready(function(){$("#stock").addClass("selected"),$("#stock a").addClass("active"),initView()});const componentFilters={locations:"",products:""};$(document).on("change","#products",function(){const t=$(this).val();componentFilters.products=t,fetchStats(),fetchList()}),$(document).on("change","#locations",function(){const t=$(this).val();componentFilters.locations=t,fetchStats(),fetchList()});